-- 0088_assess2_myp2.sql
-- MYP2 (Grade 7) Formative Assessment 2 - Criteria A-D
-- Criteria A-D formative: typed answers only, criterion+strand tagged,
-- 2 hint levels per question/part, native SVG diagrams. Idempotent.
begin;

insert into quizzes (id, organization_id, title, description, status, settings, created_by)
values ('c2000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000001', 'MYP2 (Grade 7) Formative Assessment 2 - Criteria A-D', 'Grade 7 · MYP 2 · Mathematics · Formative Assessment 2 (Criteria A–D). Rate, ratio and proportional reasoning, sets and two-set Venn diagrams, probability. Every answer is typed; hints are free and never give the answer.', 'published',
        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"formative","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","duration_minutes":45,"total_marks":57.0,"source":"assess2-myp2b-criteria"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into questions (id, organization_id, type, prompt, prompt_doc, explanation, explanation_doc,
                       points, difficulty, topic, subtopic, tags, status, config, created_by,
                       curriculum, curriculum_course, subject_id, review_status, creation_method, class_id)
select ('c2000000-0000-4000-8000' || lpad((100 + (x->>'n')::int)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', x->>'t', x->>'p', x->'d', x->>'e', null,
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st',
       array['MYP 2', 'Mathematics', 'formative', 'assess2-criteria'], 'published', x->'cfg', '3c3ed712-f409-4aa1-a645-816418e22ec4',
       'MYP', 'MYP 2 Mathematics', '0a400000-0000-4000-8000-000000000030', 'approved', 'manual', '0a400000-0000-4000-8000-000000000107'
  from jsonb_array_elements('[{"n":1,"t":"numeric","p":"The table shows the distance covered by a delivery scooter travelling at a steady speed. Calculate its speed.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table shows the distance covered by a delivery scooter travelling at a steady speed. Calculate its speed."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Scooter journey","columns":["Time (hours)","0","1","2","3"],"rows":[["Distance (km)","0","32","64","96"]]}}}]},"e":"Speed = distance ÷ time = 96 ÷ 3 = 32 km/h.\n\nHint for next time: Read the final row of the table, then divide distance by time.","m":1,"df":"easy","tp":"rate","st":"speed from a table","cfg":{"source":"assess2-myp2b-criteria","question_number":1,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"Read the final row of the table, then divide distance by time.","assessment_style":"assess2_criteria_typed","hints":["Speed links distance and time at a steady rate.","Divide the distance travelled by the time taken."],"numeric_answer":32,"tolerance":0}},{"n":2,"t":"assess_parts","p":"A necklace pattern uses gold and silver beads in the ratio 5 : 3. Complete the missing values for this ratio.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A necklace pattern uses gold and silver beads in the ratio 5 : 3. Complete the missing values for this ratio."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Gold : silver beads","columns":["Gold beads","5","10","20"],"rows":[["Silver beads","3","?","?"]]}}}]},"e":"Each row scales 5 : 3 by the same factor. ×2 gives 10 : 6; 20 gold beads is ×4, so silver = 3 × 4 = 12.\n\nHint for next time: 10 gold beads is the original amount scaled by a factor.","m":2,"df":"easy","tp":"ratio","st":"completing a ratio table","cfg":{"source":"assess2-myp2b-criteria","question_number":2,"myp_criterion":"A","strand":"A(i)","next_time_hint":"10 gold beads is the original amount scaled by a factor.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many silver beads go with 10 gold beads?","kind":"numeric","points":1,"hints":["10 gold beads is the original amount scaled by a factor.","Find the scale factor from 5 to 10, then apply it to 3."],"strand":"A(i)","answer":6,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many silver beads go with 20 gold beads?","kind":"numeric","points":1,"hints":["Work out how many times bigger 20 is than 5.","Multiply the silver value by the same scale factor."],"strand":"A(i)","answer":12,"tolerance":0}]}},{"n":3,"t":"assess_parts","p":"The tape diagram shows flour and sugar for a pastry recipe in the ratio 4 : 1. The total mass is 500 g.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The tape diagram shows flour and sugar for a pastry recipe in the ratio 4 : 1. The total mass is 500 g."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Flour : sugar (500 g in total)","tapeRows":[{"label":"Flour","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]},{"label":"Sugar","segments":[{"label":"?","span":1}]}]}}}]},"e":"There are 5 equal parts, so one part = 500 ÷ 5 = 100 g. Flour takes 4 parts: 4 × 100 = 400 g.\n\nHint for next time: Count the equal parts in the whole diagram first.","m":2,"df":"easy","tp":"proportion","st":"tape diagram proportion","cfg":{"source":"assess2-myp2b-criteria","question_number":3,"myp_criterion":"A","strand":"A(ii)","next_time_hint":"Count the equal parts in the whole diagram first.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the mass of one equal part.","kind":"numeric","points":1,"hints":["Count the equal parts in the whole diagram first.","Share 500 g equally between all the parts."],"strand":"A(ii)","answer":100,"tolerance":0,"unit":"g"},{"id":"b","label":"(b)","prompt":"Calculate the mass of flour.","kind":"numeric","points":1,"hints":["Flour has more parts than sugar — count them.","Multiply one part by the number of flour parts."],"strand":"A(ii)","answer":400,"tolerance":0,"unit":"g"}]}},{"n":4,"t":"numeric","p":"A 3D printer prints 45 cm of filament in 9 minutes at a constant rate. Calculate how many centimetres it prints in one minute.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 3D printer prints 45 cm of filament in 9 minutes at a constant rate. Calculate how many centimetres it prints in one minute."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"double_number_line","title":"Filament printed","lines":[{"label":"Time","unit":"min","max":9,"ticks":[{"at":0,"label":"0"},{"at":9,"label":"9"}]},{"label":"Filament","unit":"cm","max":45,"ticks":[{"at":0,"label":"0"},{"at":45,"label":"45"}]}]}}}]},"e":"Unit rate = 45 ÷ 9 = 5 cm per minute.\n\nHint for next time: A unit rate is the amount for ONE minute.","m":1,"df":"medium","tp":"rate","st":"unit rate","cfg":{"source":"assess2-myp2b-criteria","question_number":4,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"A unit rate is the amount for ONE minute.","assessment_style":"assess2_criteria_typed","hints":["A unit rate is the amount for ONE minute.","Divide the total length by the number of minutes."],"numeric_answer":5,"tolerance":0}},{"n":5,"t":"assess_parts","p":"The Venn diagram shows students in a class who study Art (A) and Music (M).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Venn diagram shows students in a class who study Art (A) and Music (M)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Art and Music students","venn":{"leftLabel":"A","rightLabel":"M","leftOnly":"11","both":"6","rightOnly":"8","outside":"5","universalLabel":"ξ = class"}}}}]},"e":"Art only = 11 and both = 6, so n(A) = 11 + 6 = 17. Music only = 8, so students studying exactly one subject = 11 + 8 = 19.\n\nHint for next time: Set A is the whole left circle, including the overlap.","m":2,"df":"easy","tp":"sets and Venn diagrams","st":"reading a Venn diagram","cfg":{"source":"assess2-myp2b-criteria","question_number":5,"myp_criterion":"A","strand":"A(i)","next_time_hint":"Set A is the whole left circle, including the overlap.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the value of n(A).","kind":"numeric","points":1,"hints":["Set A is the whole left circle, including the overlap.","Add the two regions inside the A circle."],"strand":"A(i)","answer":17,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many students study exactly one of the two subjects?","kind":"numeric","points":1,"hints":["Exactly one means in one circle but NOT in the overlap.","Add the two ''only'' regions and leave out the overlap."],"strand":"A(i)","answer":19,"tolerance":0}]}},{"n":6,"t":"assess_parts","p":"For the universal set ξ = {multiples of 3 up to 30}, set T is the multiples of 4 within ξ.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the universal set ξ = {multiples of 3 up to 30}, set T is the multiples of 4 within ξ."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Universal set ξ","columns":["ξ = multiples of 3 up to 30"],"rows":[["3, 6, 9, 12, 15, 18, 21, 24, 27, 30"]]}}}]},"e":"Multiples of 3 up to 30: 3, 6, 9, 12, 15, 18, 21, 24, 27, 30 (10 numbers). Of these, the multiples of 4 are 12 and 24, so n(T) = 2 and n(T′) = 10 − 2 = 8.\n\nHint for next time: Look through ξ for numbers also divisible by 4.","m":2,"df":"medium","tp":"sets and Venn diagrams","st":"complement of a set","cfg":{"source":"assess2-myp2b-criteria","question_number":6,"myp_criterion":"A","strand":"A(i)","next_time_hint":"Look through ξ for numbers also divisible by 4.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the value of n(T).","kind":"numeric","points":1,"hints":["Look through ξ for numbers also divisible by 4.","Check each multiple of 3 against divisibility by 4."],"strand":"A(i)","answer":2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write down the value of n(T′), the complement of T.","kind":"numeric","points":1,"hints":["The complement is everything in ξ outside T.","Subtract n(T) from the total number of elements in ξ."],"strand":"A(i)","answer":8,"tolerance":0}]}},{"n":7,"t":"short_answer","p":"A fair spinner has 8 equal sectors numbered 1 to 8. Write down the probability of spinning an even number, as a fraction in its simplest form.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fair spinner has 8 equal sectors numbered 1 to 8. Write down the probability of spinning an even number, as a fraction in its simplest form."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Spinner outcomes","columns":["Sector","1","2","3","4","5","6","7","8"],"rows":[["Parity","odd","even","odd","even","odd","even","odd","even"]]}}}]},"e":"Even outcomes: 2, 4, 6, 8 → 4 of 8 sectors. P(even) = 4/8 = 1/2.\n\nHint for next time: Probability = favourable outcomes ÷ total outcomes, then simplify.","m":1,"df":"easy","tp":"probability","st":"simple probability","cfg":{"source":"assess2-myp2b-criteria","question_number":7,"myp_criterion":"A","strand":"A(iii)","next_time_hint":"Probability = favourable outcomes ÷ total outcomes, then simplify.","assessment_style":"assess2_criteria_typed","hints":["Probability = favourable outcomes ÷ total outcomes, then simplify.","Count the even sectors and write them over the total number of sectors."],"accepted":["1/2","0.5","4/8","50%"]}},{"n":8,"t":"assess_parts","p":"The double number line shows that 5 notebooks cost €20 at a stationery shop.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The double number line shows that 5 notebooks cost €20 at a stationery shop."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"double_number_line","title":"Cost of notebooks","lines":[{"label":"Notebooks","unit":"books","max":9,"ticks":[{"at":0,"label":"0"},{"at":5,"label":"5"},{"at":9,"label":"?"}]},{"label":"Cost","unit":"€","max":36,"ticks":[{"at":0,"label":"0"},{"at":20,"label":"20"},{"at":36,"label":"36"}]}]}}}]},"e":"One notebook costs 20 ÷ 5 = €4. For €36: 36 ÷ 4 = 9 notebooks.\n\nHint for next time: Find the unit price first.","m":2,"df":"medium","tp":"proportion","st":"double number line","cfg":{"source":"assess2-myp2b-criteria","question_number":8,"myp_criterion":"A","strand":"A(ii)","next_time_hint":"Find the unit price first.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate the cost of one notebook.","kind":"numeric","points":1,"hints":["Find the unit price first.","Divide the cost of 5 notebooks by 5."],"strand":"A(ii)","answer":4,"tolerance":0,"unit":"€"},{"id":"b","label":"(b)","prompt":"How many notebooks can be bought for €36?","kind":"numeric","points":1,"hints":["Use the cost of one notebook.","Divide €36 by the price of a single notebook."],"strand":"A(ii)","answer":9,"tolerance":0}]}},{"n":9,"t":"numeric","p":"Six workers can paint a hall in 10 days, working at the same rate. Assuming the work is shared equally, calculate how long 15 workers would take.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Six workers can paint a hall in 10 days, working at the same rate. Assuming the work is shared equally, calculate how long 15 workers would take."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Workers and days","columns":["Workers","6","15"],"rows":[["Days","10","?"]]}}}]},"e":"Total work = 6 × 10 = 60 worker-days. With 15 workers: 60 ÷ 15 = 4 days. This is inverse proportion — more workers, fewer days.\n\nHint for next time: For inverse proportion, workers × days stays constant.","m":1,"df":"hard","tp":"proportion","st":"inverse proportion","cfg":{"source":"assess2-myp2b-criteria","question_number":9,"myp_criterion":"A","strand":"A(ii)","next_time_hint":"For inverse proportion, workers × days stays constant.","assessment_style":"assess2_criteria_typed","hints":["The total amount of work does not change — think worker-days.","Multiply workers by days for the first crew, then share that work among 15."],"numeric_answer":4,"tolerance":0}},{"n":10,"t":"assess_parts","p":"A baker investigates how the cost of croissants depends on the number bought. The bakery charges a single price per croissant with no bulk discount.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A baker investigates how the cost of croissants depends on the number bought. The bakery charges a single price per croissant with no bulk discount."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Croissant prices","columns":["Croissants","2","4","6","9"],"rows":[["Cost ($)","4.50","9.00","?","?"]]}}}]},"e":"Each croissant costs 9 ÷ 4 = $2.25. So 6 cost 6 × 2.25 = $13.50 and 9 cost $20.25. General rule: cost = 2.25 × number, so 40 croissants cost 40 × 2.25 = $90.\n\nHint for next time: Find the price of one croissant from a completed column.","m":3.0,"df":"medium","tp":"proportion","st":"pattern in proportional pricing","cfg":{"source":"assess2-myp2b-criteria","question_number":10,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Find the price of one croissant from a completed column.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the cost of 6 croissants.","kind":"numeric","points":0.5,"hints":["Find the price of one croissant from a completed column.","Divide a known cost by its number of croissants, then scale up."],"strand":"B(i)","answer":13.5,"tolerance":0.01,"unit":"$"},{"id":"b","label":"(b)","prompt":"Find the cost of 9 croissants.","kind":"numeric","points":0.5,"hints":["Use the same price per croissant as in (a).","Multiply the unit price by 9."],"strand":"B(i)","answer":20.25,"tolerance":0.01,"unit":"$"},{"id":"c","label":"(c)","prompt":"Describe the general rule: write the cost C for n croissants as a formula. Type like C=2.25n.","kind":"expression","points":1,"hints":["The cost grows by the same amount for each extra croissant.","Write C = (price of one) × n using your unit price."],"strand":"B(ii)","accepted":["C=2.25n","2.25n","C = 2.25 × n"]},{"id":"d","label":"(d)","prompt":"Verify your rule: use it to calculate the cost of 40 croissants.","kind":"numeric","points":1,"hints":["Substitute the new number into your formula from (c).","Multiply the unit price by 40."],"strand":"B(iii)","answer":90,"tolerance":0.01,"unit":"$"}]}},{"n":11,"t":"assess_parts","p":"A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Leak investigation","columns":["Time t (min)","2","4","6","10","15"],"rows":[["Volume V (L)","0.8","1.6","2.4","?","?"]]}}}]},"e":"In 2 minutes 0.8 L collects, so the rate is 0.4 L per minute. After 10 min: 4.0 L; after 15 min: 6.0 L. Rule: V = 0.4t, giving 0.4 × 60 = 24 L in one hour.\n\nHint for next time: Look at how the volume grows each 2 minutes.","m":3.0,"df":"medium","tp":"rate","st":"pattern in a steady rate","cfg":{"source":"assess2-myp2b-criteria","question_number":11,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Look at how the volume grows each 2 minutes.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the volume collected after 10 minutes.","kind":"numeric","points":0.5,"hints":["Look at how the volume grows each 2 minutes.","Find the volume per minute, then multiply by 10."],"strand":"B(i)","answer":4.0,"tolerance":0.05,"unit":"L"},{"id":"b","label":"(b)","prompt":"Find the volume collected after 15 minutes.","kind":"numeric","points":0.5,"hints":["Use the same steady rate as in (a).","Multiply the per-minute rate by 15."],"strand":"B(i)","answer":6.0,"tolerance":0.05,"unit":"L"},{"id":"c","label":"(c)","prompt":"Write a general rule for V in terms of t. Type like V=0.4t.","kind":"expression","points":1,"hints":["The volume starts at 0 and grows steadily with time.","Write V = (volume per minute) × t."],"strand":"B(ii)","accepted":["V=0.4t","0.4t","V = 0.4 × t"]},{"id":"d","label":"(d)","prompt":"Verify your rule for one hour (60 minutes). How many litres collect?","kind":"numeric","points":1,"hints":["Substitute t = 60 into your rule.","Multiply your per-minute rate by 60."],"strand":"B(iii)","answer":24,"tolerance":0.1,"unit":"L"}]}},{"n":12,"t":"assess_parts","p":"A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Tile motif investigation","columns":["Size n","1","2","3","4","5"],"rows":[["Dark tiles","3","5","7","9","?"],["Light tiles","5","8","11","14","?"]]}}}]},"e":"Dark tiles: 3, 5, 7, 9 → increases by 2; light tiles: 5, 8, 11, 14 → increases by 3. Size 5: dark = 11, light = 17. Rule: dark = 2n + 1, so size 20 has 2 × 20 + 1 = 41 dark tiles.\n\nHint for next time: Look at the step from one size to the next in the dark row.","m":3.0,"df":"hard","tp":"ratio","st":"two growing sequences","cfg":{"source":"assess2-myp2b-criteria","question_number":12,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Look at the step from one size to the next in the dark row.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the number of dark tiles in size 5.","kind":"numeric","points":0.5,"hints":["Look at the step from one size to the next in the dark row.","Continue the dark-tile pattern by its constant step."],"strand":"B(i)","answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the number of light tiles in size 5.","kind":"numeric","points":0.5,"hints":["The light row has its own constant step — find it.","Continue the light-tile pattern by its step."],"strand":"B(i)","answer":17,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write a general rule for the number of dark tiles D in size n. Type like D=2n+1.","kind":"expression","points":1,"hints":["Compare each dark value with double the size number.","Use the step as the multiplier of n, then adjust with a constant."],"strand":"B(ii)","accepted":["D=2n+1","2n+1"]},{"id":"d","label":"(d)","prompt":"Verify your rule: how many dark tiles are in size 20?","kind":"numeric","points":1,"hints":["Substitute n = 20 into your rule from (c).","Multiply 20 by the step and add the constant."],"strand":"B(iii)","answer":41,"tolerance":0}]}},{"n":13,"t":"assess_parts","p":"A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Drawing pin experiment","columns":["Drops","50","100","200","400"],"rows":[["Point-up","34","63","130","…"],["Relative frequency","0.68","0.63","0.65","…"]]}}}]},"e":"Relative frequency after 200 drops = 130/200 = 0.65. In 1000 drops at 0.65, expect about 650 point-up landings. The estimate settles near 0.65 as trials increase; 400 drops at 0.65 gives 260.\n\nHint for next time: Relative frequency = frequency ÷ total trials.","m":3.0,"df":"medium","tp":"probability","st":"experimental probability pattern","cfg":{"source":"assess2-myp2b-criteria","question_number":13,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Relative frequency = frequency ÷ total trials.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the relative frequency of point-up after 200 drops, as a decimal.","kind":"numeric","points":0.5,"hints":["Relative frequency = frequency ÷ total trials.","Divide the point-up count by 200."],"strand":"B(i)","answer":0.65,"tolerance":0.005},{"id":"b","label":"(b)","prompt":"Predict how many point-up landings you would expect in 1000 drops, using the 200-drop result.","kind":"numeric","points":0.5,"hints":["Scale the relative frequency up to 1000 drops.","Multiply your decimal from (a) by 1000."],"strand":"B(i)","answer":650,"tolerance":0},{"id":"c","label":"(c)","prompt":"Describe the pattern in the relative frequencies as the number of drops increases. Type one short phrase: does it settle, rise steadily, or fall steadily?","kind":"text","points":1,"hints":["Compare 0.68, 0.63 and 0.65 — are they moving in one direction?","Decide whether the values hover around one number or keep drifting."],"strand":"B(ii)","accepted":["it settles","settles","it settles near 0.65","settles near 0.65","it becomes more stable"],"keywords":[["settles","stable","steady around"]],"minKeywordGroups":1},{"id":"d","label":"(d)","prompt":"Verify: using the settled relative frequency, predict point-up landings in 400 drops.","kind":"numeric","points":1,"hints":["Use the relative frequency from (a) as the settled value.","Multiply 400 by your decimal from (a)."],"strand":"B(iii)","answer":260,"tolerance":0}]}},{"n":14,"t":"assess_parts","p":"A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Orchestra and Choir","venn":{"leftLabel":"O","rightLabel":"C","leftOnly":"?","both":"8","rightOnly":"?","outside":"?","universalLabel":"ξ = 50 students"}}}}]},"e":"n(O only) = 26 − 8 = 18. n(O ∪ C) = 26 + 19 − 8 = 37, so neither = 50 − 37 = 13. Pattern: n(O ∪ C) = n(O) + n(C) − n(both) — check: 26 + 19 − 8 = 37 ✓.\n\nHint for next time: The 26 includes students who also sing in the choir.","m":3.0,"df":"hard","tp":"sets and Venn diagrams","st":"discovering the union rule","cfg":{"source":"assess2-myp2b-criteria","question_number":14,"myp_criterion":"B","strand":"B(i)","next_time_hint":"The 26 includes students who also sing in the choir.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the number of students in the orchestra only.","kind":"numeric","points":0.5,"hints":["The 26 includes students who also sing in the choir.","Subtract the ''both'' region from the orchestra total."],"strand":"B(i)","answer":18,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many students are in neither club?","kind":"numeric","points":0.5,"hints":["First find how many are in at least one club.","Add the club totals, subtract the double-counted overlap, then subtract from 50."],"strand":"B(i)","answer":13,"tolerance":0},{"id":"c","label":"(c)","prompt":"State the general rule connecting n(O ∪ C), n(O), n(C) and n(O ∩ C). Type like n(O)+n(C)-n(both).","kind":"text","points":1,"hints":["Why did you subtract the overlap in part (b)?","The overlap is counted twice when the two sets are added."],"strand":"B(ii)","accepted":["n(O)+n(C)-n(both)","n(O) + n(C) − n(O ∩ C)","add both sets then subtract the overlap","n(O)+n(C)-n(O∩C)"],"keywords":[["add","sum"],["subtract","minus"],["overlap","both","intersection","counted twice"]],"minKeywordGroups":2},{"id":"d","label":"(d)","prompt":"Verify the rule with the numbers: type the value of n(O) + n(C) − n(both).","kind":"numeric","points":1,"hints":["Substitute the three given totals into your rule.","Add the two club sizes and subtract the both count."],"strand":"B(iii)","answer":37,"tolerance":0}]}},{"n":15,"t":"assess_parts","p":"A print shop investigates paper costs. The table shows the cost of printing booklets when the same price per booklet applies.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A print shop investigates paper costs. The table shows the cost of printing booklets when the same price per booklet applies."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Booklet printing costs","columns":["Booklets n","4","12","20","35"],"rows":[["Cost C ($)","10","30","?","?"]]}}}]},"e":"12 booklets cost $30, so one booklet costs $2.50. Cost for 20: $50; for 35: $87.50. Rule: C = 2.5n, so 100 booklets cost $250.\n\nHint for next time: Find the price of one booklet first.","m":3.0,"df":"hard","tp":"proportion","st":"linear cost pattern","cfg":{"source":"assess2-myp2b-criteria","question_number":15,"myp_criterion":"B","strand":"B(i)","next_time_hint":"Find the price of one booklet first.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the cost of printing 20 booklets.","kind":"numeric","points":0.5,"hints":["Find the price of one booklet first.","Divide a known cost by its booklet count, then scale to 20."],"strand":"B(i)","answer":50,"tolerance":0.01,"unit":"$"},{"id":"b","label":"(b)","prompt":"Find the cost of printing 35 booklets.","kind":"numeric","points":0.5,"hints":["Use the same price per booklet.","Multiply the unit price by 35."],"strand":"B(i)","answer":87.5,"tolerance":0.01,"unit":"$"},{"id":"c","label":"(c)","prompt":"Write the general rule for the cost C of n booklets. Type like C=2.5n.","kind":"expression","points":1,"hints":["The cost is proportional to the number of booklets.","Write C = (unit price) × n."],"strand":"B(ii)","accepted":["C=2.5n","2.5n","C=2.50n"]},{"id":"d","label":"(d)","prompt":"Verify your rule: calculate the cost of 100 booklets.","kind":"numeric","points":1,"hints":["Substitute n = 100 into your rule.","Multiply the unit price by 100."],"strand":"B(iii)","answer":250,"tolerance":0.01,"unit":"$"}]}},{"n":16,"t":"short_answer","p":"A squash drink mixes juice and water. Write down the ratio of juice to water, in its simplest form, from the tape diagram.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A squash drink mixes juice and water. Write down the ratio of juice to water, in its simplest form, from the tape diagram."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Juice : water in the squash","tapeRows":[{"label":"Juice","segments":[{"label":"","span":1,"shade":true},{"label":"","span":1,"shade":true},{"label":"","span":1,"shade":true},{"label":"","span":1,"shade":true},{"label":"","span":1,"shade":true},{"label":"","span":1,"shade":true}]},{"label":"Water","segments":[{"label":"","span":1},{"label":"","span":1},{"label":"","span":1},{"label":"","span":1}]}]}}}]},"e":"There are 6 juice segments and 4 water segments, so juice : water = 6 : 4 = 3 : 2.\n\nHint for next time: Count the equal segments for juice and for water separately.","m":2,"df":"easy","tp":"ratio","st":"ratio notation from a diagram","cfg":{"source":"assess2-myp2b-criteria","question_number":16,"myp_criterion":"C","strand":"C(i)","next_time_hint":"Count the equal segments for juice and for water separately.","assessment_style":"assess2_criteria_typed","hints":["Count the equal segments for juice and for water separately.","Write juice : water from the counts, then simplify by the common factor."],"accepted":["3:2","3 : 2","3/2"]}},{"n":17,"t":"assess_parts","p":"Use the Venn diagram, which shows students who take the bus (B) and cycle (C), to answer with correct set notation.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the Venn diagram, which shows students who take the bus (B) and cycle (C), to answer with correct set notation."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Getting to school","venn":{"leftLabel":"B","rightLabel":"C","leftOnly":"9","both":"4","rightOnly":"7","outside":"6","universalLabel":"ξ = students"}}}}]},"e":"Bus only = 9. The overlap (B ∩ C) = 4. Students NOT cycling include bus-only and outside: n(C′) = 9 + 6 = 15.\n\nHint for next time: ∩ means ''and'' — the overlap of the two circles.","m":2,"df":"medium","tp":"sets and Venn diagrams","st":"set notation ∪ ∩ ′","cfg":{"source":"assess2-myp2b-criteria","question_number":17,"myp_criterion":"C","strand":"C(i)","next_time_hint":"∩ means ''and'' — the overlap of the two circles.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the value of n(B ∩ C).","kind":"numeric","points":1,"hints":["∩ means ''and'' — the overlap of the two circles.","Read the value in the region shared by both circles."],"strand":"C(i)","answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write down the value of n(C′).","kind":"numeric","points":1,"hints":["C′ is everything outside the C circle, but inside ξ.","Add the regions that lie outside the cycling circle."],"strand":"C(i)","answer":15,"tolerance":0}]}},{"n":18,"t":"assess_parts","p":"The graph shows the cost of hiring a kayak, where cost is proportional to time. Move between the graph and numbers.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The graph shows the cost of hiring a kayak, where cost is proportional to time. Move between the graph and numbers."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Kayak hire cost","xLabel":"Time (hours)","yLabel":"Cost ($)","xMin":0,"xMax":6,"yMin":0,"yMax":30,"points":[[0,0],[1,5],[2,10],[3,15],[4,20],[5,25],[6,30]],"joinPoints":true}}}]},"e":"The line passes through (2, 10), so one hour costs $5. Three hours cost $15; $25 buys 5 hours.\n\nHint for next time: Find 3 on the time axis, go up to the line, then across.","m":2,"df":"medium","tp":"proportion","st":"graph to numbers","cfg":{"source":"assess2-myp2b-criteria","question_number":18,"myp_criterion":"C","strand":"C(iii)","next_time_hint":"Find 3 on the time axis, go up to the line, then across.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Use the graph to find the cost of 3 hours.","kind":"numeric","points":1,"hints":["Find 3 on the time axis, go up to the line, then across.","Read the cost value level with 3 hours on the graph."],"strand":"C(iii)","answer":15,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"How many hours can be hired for $25?","kind":"numeric","points":1,"hints":["Start from $25 on the cost axis this time.","Go across to the line from 25, then down to the time axis."],"strand":"C(iii)","answer":5,"tolerance":0,"unit":"hours"}]}},{"n":19,"t":"assess_parts","p":"Find the error. A student writes: \"A train travels 180 km in 3 hours, so its speed is 180 × 3 = 540 km/h.\" Type the correct speed.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the error. A student writes: \"A train travels 180 km in 3 hours, so its speed is 180 × 3 = 540 km/h.\" Type the correct speed."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Train journey","columns":["Distance","180 km"],"rows":[["Time","3 hours"]]}}}]},"e":"Speed = distance ÷ time = 180 ÷ 3 = 60 km/h. The student multiplied instead of dividing, giving an impossible speed.\n\nHint for next time: Speed is distance per unit of time — which operation gives ''per hour''?","m":2,"df":"medium","tp":"rate","st":"find the error","cfg":{"source":"assess2-myp2b-criteria","question_number":19,"myp_criterion":"C","strand":"C(iv)","next_time_hint":"Speed is distance per unit of time — which operation gives ''per hour''?","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Type the correct speed.","kind":"numeric","points":1,"hints":["Speed is distance per unit of time — which operation gives ''per hour''?","Divide the distance by the time."],"strand":"C(iv)","answer":60,"tolerance":0,"unit":"km/h"},{"id":"b","label":"(b)","prompt":"Explain the student''s error in one short sentence.","kind":"text","points":1,"hints":["Compare the student''s operation with the correct one.","Name the operation they used and the one they should have used."],"strand":"C(iv)","accepted":["they multiplied instead of dividing","multiplied instead of dividing","they multiplied rather than divided"],"keywords":[["multiplied","multiply","times"],["divid","division"]],"minKeywordGroups":2}]}},{"n":20,"t":"assess_parts","p":"The outcome table shows all results when two coins are tossed together. Complete the probability statement using the table.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The outcome table shows all results when two coins are tossed together. Complete the probability statement using the table."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Two-coin outcomes","columns":["Coin 1 \\ Coin 2","H","T"],"rows":[["H","HH","HT"],["T","TH","TT"]]}}}]},"e":"There are 4 equally likely outcomes. Two heads (HH) is 1 outcome → P = 1/4. Exactly one head (HT, TH) is 2 outcomes → P = 1/2.\n\nHint for next time: Count the HH cells out of all the cells in the table.","m":2,"df":"hard","tp":"probability","st":"outcome table representation","cfg":{"source":"assess2-myp2b-criteria","question_number":20,"myp_criterion":"C","strand":"C(ii)","next_time_hint":"Count the HH cells out of all the cells in the table.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down P(two heads) as a simplified fraction.","kind":"text","points":1,"hints":["Count the HH cells out of all the cells in the table.","Write favourable cells over total cells and simplify."],"strand":"C(ii)","accepted":["1/4","0.25","25%"]},{"id":"b","label":"(b)","prompt":"Write down P(exactly one head) as a simplified fraction.","kind":"text","points":1,"hints":["Look for cells with exactly one H.","Count those cells and write them over the total, then simplify."],"strand":"C(ii)","accepted":["1/2","2/4","0.5"]}]}},{"n":21,"t":"assess_parts","p":"A decorator mixes green paint from blue and yellow in the ratio 3 : 7. She needs 20 litres of green paint for a community hall.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A decorator mixes green paint from blue and yellow in the ratio 3 : 7. She needs 20 litres of green paint for a community hall."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Blue : yellow (ratio 3 : 7)","tapeRows":[{"label":"Blue","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]},{"label":"Yellow","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]}]}}}]},"e":"Total parts = 10, so one part = 2 L. Blue = 3 × 2 = 6 L; yellow = 7 × 2 = 14 L. Check: 6 + 14 = 20 ✓. Paint is sold in 1-litre tins, so whole litres are exact here — 6 tins of blue.\n\nHint for next time: Add the two numbers in the ratio.","m":3.0,"df":"medium","tp":"proportion","st":"paint mixing job","cfg":{"source":"assess2-myp2b-criteria","question_number":21,"myp_criterion":"D","strand":"D(i)","next_time_hint":"Add the two numbers in the ratio.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify the total number of equal parts in the mix.","kind":"numeric","points":0.5,"hints":["Add the two numbers in the ratio.","Combine the blue and yellow parts."],"strand":"D(i)","answer":10,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the litres of blue paint needed.","kind":"numeric","points":1,"hints":["Share 20 litres into the equal parts first.","Find one part from 20 litres, then take the blue share."],"strand":"D(ii)","answer":6,"tolerance":0,"unit":"litres"},{"id":"c","label":"(c)","prompt":"Calculate the litres of yellow paint needed.","kind":"numeric","points":1,"hints":["Yellow takes the larger share.","Take the yellow parts of the 20 litres — or subtract blue from 20."],"strand":"D(iii)","answer":14,"tolerance":0,"unit":"litres"},{"id":"d","label":"(d)","prompt":"The answer is exact to the litre. State whether buying 6 one-litre tins of blue is enough: type yes or no.","kind":"text","points":0.5,"hints":["Compare the blue needed with what 6 tins provide.","6 tins hold 6 litres — compare with your answer to (b)."],"strand":"D(iv)","accepted":["yes"],"keywords":[["yes"]],"minKeywordGroups":1}]}},{"n":22,"t":"assess_parts","p":"On a school trip, a coach travels 264 km in 4 hours on the motorway, then a further 45 km in 1.5 hours on country roads.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a school trip, a coach travels 264 km in 4 hours on the motorway, then a further 45 km in 1.5 hours on country roads."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Coach journey","columns":["Leg","Distance (km)","Time (h)"],"rows":[["Motorway","264","4"],["Country roads","45","1.5"]]}}}]},"e":"Motorway speed = 264 ÷ 4 = 66 km/h. Country speed = 45 ÷ 1.5 = 30 km/h. Overall average = total distance ÷ total time = 309 ÷ 5.5 = 56.18 km/h (2 d.p.). Note the average is not the mean of 66 and 30, because the times differ.\n\nHint for next time: Speed = distance ÷ time for that leg.","m":3.0,"df":"medium","tp":"rate","st":"school trip speeds","cfg":{"source":"assess2-myp2b-criteria","question_number":22,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Speed = distance ÷ time for that leg.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate the coach''s speed on the motorway.","kind":"numeric","points":0.5,"hints":["Speed = distance ÷ time for that leg.","Divide the motorway distance by its time."],"strand":"D(ii)","answer":66,"tolerance":0,"unit":"km/h"},{"id":"b","label":"(b)","prompt":"Calculate the coach''s speed on the country roads.","kind":"numeric","points":1,"hints":["Use the same relationship on the second leg.","Divide the country distance by its time."],"strand":"D(iii)","answer":30,"tolerance":0,"unit":"km/h"},{"id":"c","label":"(c)","prompt":"Calculate the average speed for the whole journey, to 2 decimal places.","kind":"numeric","points":1,"hints":["Average speed uses the TOTALS, not the mean of the two speeds.","Add both distances and both times, then divide."],"strand":"D(iii)","answer":56.18,"tolerance":0.01,"unit":"km/h"},{"id":"d","label":"(d)","prompt":"State whether 56 km/h is a sensible rounded value to quote for the journey: type yes or no.","kind":"text","points":0.5,"hints":["Compare 56 with your 2 d.p. answer.","Check whether rounding to the nearest whole number is reasonable."],"strand":"D(v)","accepted":["yes"],"keywords":[["yes"]],"minKeywordGroups":1}]}},{"n":23,"t":"assess_parts","p":"A school surveys 40 students about the canteen: 23 buy fruit (F), 17 buy yoghurt (Y), and 9 buy both. The canteen manager uses the results to plan stock.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A school surveys 40 students about the canteen: 23 buy fruit (F), 17 buy yoghurt (Y), and 9 buy both. The canteen manager uses the results to plan stock."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Canteen survey","venn":{"leftLabel":"F","rightLabel":"Y","leftOnly":"?","both":"9","rightOnly":"?","outside":"?","universalLabel":"ξ = 40 students"}}}}]},"e":"Fruit only = 23 − 9 = 14. Neither = 40 − (23 + 17 − 9) = 40 − 31 = 9. So 9 students buy neither item and the manager need not stock for them.\n\nHint for next time: The fruit total includes students who also buy yoghurt.","m":3.0,"df":"hard","tp":"sets and Venn diagrams","st":"school survey","cfg":{"source":"assess2-myp2b-criteria","question_number":23,"myp_criterion":"D","strand":"D(i)","next_time_hint":"The fruit total includes students who also buy yoghurt.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find how many students buy fruit only.","kind":"numeric","points":0.5,"hints":["The fruit total includes students who also buy yoghurt.","Subtract the both region from the fruit total."],"strand":"D(i)","answer":14,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find how many students buy neither item.","kind":"numeric","points":1,"hints":["First find how many buy at least one item.","Add the two totals, subtract the double-counted overlap, then subtract from 40."],"strand":"D(ii)","answer":9,"tolerance":0},{"id":"c","label":"(c)","prompt":"How many students buy at least one of the two items?","kind":"numeric","points":1,"hints":["At least one is the union of the two sets.","Combine both totals and remove the overlap counted twice."],"strand":"D(iii)","answer":31,"tolerance":0},{"id":"d","label":"(d)","prompt":"Justify, in one short phrase, whether the manager should stock fruit for all 40 students: type ''no, only 23 buy fruit'' or explain briefly.","kind":"text","points":0.5,"hints":["How many students actually buy fruit?","Use the given fruit total, not the whole survey group."],"strand":"D(v)","accepted":["no, only 23 buy fruit","no","no - only 23 buy fruit"],"keywords":[["no"],["23"]],"minKeywordGroups":1}]}},{"n":24,"t":"assess_parts","p":"A fairground game uses a spinner with 10 equal sectors: 3 are gold (win), the rest are blank. A stallholder tests the game fairly before opening.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fairground game uses a spinner with 10 equal sectors: 3 are gold (win), the rest are blank. A stallholder tests the game fairly before opening."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Fairground spinner","columns":["Sector type","Gold (win)","Blank"],"rows":[["Sectors","3","7"]]}}}]},"e":"P(win) = 3/10 = 0.3. In 50 spins, expect 0.3 × 50 = 15 wins. A prize costs the stallholder $2, so expected payout ≈ 15 × 2 = $30 per 50 spins — an estimate, since actual wins vary.\n\nHint for next time: Probability = winning sectors ÷ all sectors.","m":3.0,"df":"medium","tp":"probability","st":"fairground game","cfg":{"source":"assess2-myp2b-criteria","question_number":24,"myp_criterion":"D","strand":"D(ii)","next_time_hint":"Probability = winning sectors ÷ all sectors.","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down P(win) as a decimal.","kind":"numeric","points":0.5,"hints":["Probability = winning sectors ÷ all sectors.","Write the gold sectors over the total sectors as a decimal."],"strand":"D(ii)","answer":0.3,"tolerance":0.005},{"id":"b","label":"(b)","prompt":"Predict the number of wins in 50 spins.","kind":"numeric","points":1,"hints":["Scale the probability up to 50 spins.","Multiply your probability by 50."],"strand":"D(iii)","answer":15,"tolerance":0},{"id":"c","label":"(c)","prompt":"Each win costs the stallholder $2 in prizes. Calculate the expected payout for 50 spins.","kind":"numeric","points":1,"hints":["Use your predicted number of wins.","Multiply the predicted wins by the prize cost."],"strand":"D(iii)","answer":30,"tolerance":0,"unit":"$"},{"id":"d","label":"(d)","prompt":"Explain in a few words why the actual payout might differ from your estimate.","kind":"text","points":0.5,"hints":["Is the number of wins in 50 spins guaranteed?","Think about chance: results vary from trial to trial."],"strand":"D(iv)","accepted":["results vary by chance","it is only an estimate","actual results vary"],"keywords":[["vary","varies","variation","chance","random","estimate","not guaranteed"]],"minKeywordGroups":1}]}},{"n":25,"t":"assess_parts","p":"A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs $1.60 per litre.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs "},{"type":"text","text":"$1.60 per litre."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Family road trip","columns":["Journey","420 km"],"rows":[["Fuel rate","7.5 L per 100 km"],["Fuel price","$1.60 per litre"]]}}}]},"e":"Fuel needed = 420 × 7.5/100 = 31.5 litres. Cost = 31.5 × 1.60 = $50.40. The rate is a manufacturer''s average, so the true cost may differ slightly with driving conditions — quoting about $50 is sensible.\n\nHint for next time: How many hundreds fit into 420?","m":3.0,"df":"hard","tp":"rate","st":"fuel-consumption trip","cfg":{"source":"assess2-myp2b-criteria","question_number":25,"myp_criterion":"D","strand":"D(i)","next_time_hint":"How many hundreds fit into 420?","assessment_style":"assess2_criteria_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Identify how many 100 km units are in the journey (type the number).","kind":"numeric","points":0.5,"hints":["How many hundreds fit into 420?","Divide the distance by 100."],"strand":"D(i)","answer":4.2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the litres of fuel needed.","kind":"numeric","points":1,"hints":["Multiply the rate by the number of 100 km units.","Use your answer to (a) with the litres per 100 km."],"strand":"D(ii)","answer":31.5,"tolerance":0.05,"unit":"litres"},{"id":"c","label":"(c)","prompt":"Calculate the cost of the fuel.","kind":"numeric","points":1,"hints":["Multiply litres by price per litre.","Use your litres from (b) and the price given."],"strand":"D(iii)","answer":50.4,"tolerance":0.05,"unit":"$"},{"id":"d","label":"(d)","prompt":"State, in a few words, why the real cost might not be exactly $50.40.","kind":"text","points":0.5,"hints":["Is a fuel-consumption rate exact in real driving?","Consider traffic, speed and driving conditions."],"strand":"D(iv)","accepted":["the rate is an average","rate varies with driving conditions","traffic and speed affect fuel use"],"keywords":[["average","vary","varies","traffic","conditions","speed","estimate"]],"minKeywordGroups":1}]}}]'::jsonb) as x
on conflict (id) do nothing;

insert into question_options (id, question_id, label, is_correct, position)
select ('c2000000-0000-4000-8000' || lpad((300000 + (q.config->>'question_number')::int * 100 + (v.idx - 1))::text, 12, '0'))::uuid,
       q.id, v.variant, true, v.idx::int
  from questions q
  cross join lateral jsonb_array_elements_text(q.config->'accepted') with ordinality as v(variant, idx)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess2-myp2b-criteria'
on conflict (id) do nothing;

insert into quiz_questions (quiz_id, question_id, position, points)
select 'c2000000-0000-4000-8000-000000000001', q.id, (q.config->>'question_number')::int, q.points
  from questions q
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess2-myp2b-criteria'
on conflict (quiz_id, question_id) do nothing;

insert into exams (id, organization_id, quiz_id, class_id, title, description, instructions, duration_minutes, status, access_code, shared_link_enabled, settings, created_by)
values ('c2000000-0000-4000-8000-000000000002', '0a400000-0000-4000-8000-000000000001', 'c2000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000107', 'MYP2 (Grade 7) Formative Assessment 2 - Criteria A-D', 'Grade 7 · MYP 2 · Mathematics · Formative Assessment 2 (Criteria A–D). Rate, ratio and proportional reasoning, sets and two-set Venn diagrams, probability. Every answer is typed; hints are free and never give the answer.',
  'Type every answer in the box provided — there are no options to choose from. Each question shows its MYP criterion and strand. Multi-part questions have a separate box and separate marks for each part. Press the Hint button whenever you are stuck: hints show you the way but never give the answer, and using a hint costs no marks. You have 45 minutes. Your feedback shows the correct answer, a worked solution, a hint for next time, and your score by criterion A-D with an indicative MYP level band.',
